// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address user) public {
        vm.assume(user != address(this) && user != address(0));
        // Grant authorization to user first
        c.rely(user);
        // Now deny should revoke, but the bug grants instead
        c.deny(user);
        // After deny, user should not be authorized
        assertTrue(c.wards(user) == 0);
    }
}

